_REGION_REPORT_COMPARE_SCHEMA = "climate-grid/rr-compare-v1"
_REGION_REPORT_COMPARE_RESULT_KEYS = (
    "schema",
    "years",
    "reference",
    "baseline",
    "scenarios",
    "elements",
    "windows",
    "regions",
    "data",
)
_REGION_REPORT_COMPARE_ROW_KEYS = (
    "scenario",
    "window",
    "region",
    "element",
    "difference",
